"""Hash the review boundary; generated files and evidence are identified separately."""
from pathlib import Path
import hashlib
import json

root = Path(__file__).resolve().parent.parent
sources, evidence, artifacts = [], [], []
for path in sorted(root.rglob('*')):
    if not path.is_file():
        continue
    relative = path.relative_to(root).as_posix()
    if relative.startswith('.build/'):
        if relative in [
            '.build/Uploadimg Desktop.app/Contents/MacOS/UploadimgDesktop',
            '.build/Uploadimg Desktop.app/Contents/Frameworks/libUploadimgNative.dylib',
            '.build/Uploadimg Desktop.app/Contents/Info.plist',
            '.build/Uploadimg Desktop.app/Contents/_CodeSignature/CodeResources',
        ]:
            artifacts.append({'path': relative, 'sha256': hashlib.sha256(path.read_bytes()).hexdigest()})
        continue
    if 'evidence/' in relative and path.name != 'README.md':
        if relative == 'evidence/source-snapshot.json':
            continue
        evidence.append({'path': relative, 'sha256': hashlib.sha256(path.read_bytes()).hexdigest()})
        continue
    generated = relative == 'Cargo.lock' or relative.startswith(('src-tauri/gen/', 'src-tauri/permissions/autogenerated/', 'src-tauri/icons/'))
    data = path.read_bytes()
    try:
        lines = len(data.decode().splitlines())
    except UnicodeDecodeError:
        lines = 0
    sources.append({'path': relative, 'sha256': hashlib.sha256(data).hexdigest(), 'lines': lines, 'generated': generated})

digest = hashlib.sha256(''.join(entry['path'] + '\0' + entry['sha256'] + '\n' for entry in sources).encode()).hexdigest()
receipt = {
    'algorithm': 'SHA256 of sorted relative-path NUL file-digest LF records',
    'snapshot': digest,
    'authoredLines': sum(entry['lines'] for entry in sources if not entry['generated']),
    'files': sources, 'evidence': evidence, 'artifacts': artifacts,
}
(root / 'evidence/source-snapshot.json').write_text(json.dumps(receipt, indent=2) + '\n')
print(json.dumps({'snapshot': digest, 'authoredLines': receipt['authoredLines'], 'sourceFiles': len(sources),
                  'evidenceFiles': len(evidence), 'artifacts': artifacts}, indent=2))
